PRAGMA foreign_keys = ON;
CREATE TABLE VehicleClass (ClassId INTEGER PRIMARY KEY, Name TEXT NOT NULL, Description TEXT);
CREATE TABLE Road (RoadId INTEGER PRIMARY KEY, Code TEXT NOT NULL UNIQUE, Name TEXT NOT NULL, LengthKm REAL NOT NULL CHECK (LengthKm > 0));
CREATE TABLE TollPoint (PointId INTEGER PRIMARY KEY, RoadId INTEGER NOT NULL REFERENCES Road (RoadId), Name TEXT NOT NULL, Km REAL NOT NULL);
CREATE TABLE Tariff (TariffId INTEGER PRIMARY KEY, RoadId INTEGER NOT NULL REFERENCES Road (RoadId), ClassId INTEGER NOT NULL REFERENCES VehicleClass (ClassId), PricePerKm REAL NOT NULL CHECK (PricePerKm >= 0), ValidFrom TEXT NOT NULL, UNIQUE (RoadId, ClassId, ValidFrom));
CREATE TABLE Client (ClientId INTEGER PRIMARY KEY, FullName TEXT NOT NULL, Phone TEXT, Email TEXT, Balance REAL NOT NULL DEFAULT 0);
CREATE TABLE Vehicle (VehicleId INTEGER PRIMARY KEY, ClientId INTEGER NOT NULL REFERENCES Client (ClientId), PlateNumber TEXT NOT NULL UNIQUE, ClassId INTEGER NOT NULL REFERENCES VehicleClass (ClassId), TransponderNo TEXT UNIQUE);
CREATE TABLE AppUser (UserId INTEGER PRIMARY KEY, Login TEXT NOT NULL UNIQUE, PasswordHash TEXT NOT NULL, Role TEXT NOT NULL CHECK (Role IN ('admin', 'operator', 'accountant')));
CREATE TABLE Trip (TripId INTEGER PRIMARY KEY, VehicleId INTEGER NOT NULL REFERENCES Vehicle (VehicleId), EntryPointId INTEGER NOT NULL REFERENCES TollPoint (PointId), ExitPointId INTEGER NOT NULL REFERENCES TollPoint (PointId), EntryTime TEXT NOT NULL, ExitTime TEXT, Cost REAL NOT NULL, Status TEXT NOT NULL CHECK (Status IN ('paid', 'debt')), OperatorId INTEGER REFERENCES AppUser (UserId));
CREATE TABLE Payment (PaymentId INTEGER PRIMARY KEY, ClientId INTEGER NOT NULL REFERENCES Client (ClientId), TripId INTEGER REFERENCES Trip (TripId), Amount REAL NOT NULL CHECK (Amount > 0), PayTime TEXT NOT NULL, Kind TEXT NOT NULL CHECK (Kind IN ('topup', 'trip')), Method TEXT NOT NULL CHECK (Method IN ('card', 'cash', 'transponder')));
